-- Test-only read-only component metadata; expressions copied verbatim from the V2 catalog.
SET NOCOUNT ON;
DECLARE @Owned table(Name sysname PRIMARY KEY); INSERT @Owned VALUES (N'AiProductCapability'),(N'TenantAiIntegrationPolicy'),(N'AiIntegrationRegistration'),(N'AiIntegrationRedirect'),(N'AiIntegrationClientKey'),(N'AiDelegationGrant'),(N'AiConsentIntent'),(N'AiDelegatedSession'),(N'AiOAuthCredential'),(N'AiQuotaReservation'),(N'AiLockV1'),(N'AiActorV1'),(N'AiEnabledV1'),(N'AiSetProductCapabilityV1'),(N'AiGetProductCapabilityV1'),(N'AiGetTenantPolicyV1'),(N'AiInspectKeysV1'),(N'AiSetTenantPolicyV1'),(N'AiRegisterIntegrationV1'),(N'AiChangeIntegrationV1'),(N'AiRotateClientKeyV1'),(N'AiRevokeClientKeyV1'),(N'AiBeginConsentV1'),(N'AiAcceptConsentV1'),(N'AiRevokeGrantV1'),(N'AiRevokeSessionV1'),(N'AiInspectRegistrationsV1'),(N'AiVerifySessionV1'),(N'AiReserveQuotaV1'),(N'AiReleaseQuotaV1'),(N'ResolveAiClientV1'),(N'ResolveAiCredentialV1'),(N'AiImmutable_TenantAiIntegrationPolicy'),(N'AiImmutable_AiIntegrationRegistration'),(N'AiImmutable_AiIntegrationRedirect'),(N'AiImmutable_AiIntegrationClientKey'),(N'AiImmutable_AiDelegationGrant'),(N'AiImmutable_AiConsentIntent'),(N'AiImmutable_AiDelegatedSession'),(N'AiImmutable_AiOAuthCredential'),(N'AiImmutable_AiQuotaReservation'),(N'AiAuthorizationTransaction'),(N'AiImmutable_AiAuthorizationTransaction'),(N'AiLoadOAuthClientV1'),(N'AiBeginOAuthV1'),(N'AiFindOAuthIntentV1'),(N'AiApproveOAuthV1'),(N'AiCompleteOAuthV1'),(N'AiDenyOAuthV1'),(N'AiConsumeOAuthCodeV1'),(N'AiAssertionReplay'),(N'ResolveAiOAuthCodeV1'),(N'AiExchangeOAuthCodeV1'),(N'ResolveAiRefreshV1'),(N'AiIssueCredentialsV1'),(N'AiRefreshCredentialsV1'),(N'AiLifecycle_Session'),(N'AiLifecycle_Credential'),(N'AiCascade_Grant'),(N'AiCascade_Key'),(N'AiCascade_Registration'),(N'AiCascade_Web'),(N'AiCascade_User'),(N'AiCascade_Tenant'); INSERT @Owned VALUES (N'ResolveAiRevocationV1'),(N'AiLoadRevocationClientV1'),(N'AiRevokeOAuthCredentialV1');
INSERT @Owned VALUES (N'ResolveAiAccessV1'),(N'AiValidateAccessV1');
INSERT @Owned VALUES (N'IntegrationAccessAuditLog'),(N'IntegrationAccessAuditResource'),(N'AiAppendCaseAccessV1'),(N'AiReviewCaseAccessV1'),(N'AiGateCaseReadV1'),(N'AiFinishCaseQuotaV1'),(N'AiAppendOnly_Access'),(N'AiAppendOnly_Resource'),(N'AiOverviewPhiCountV1'),(N'AiAccountCaseAttemptV1');
INSERT @Owned VALUES (N'AiDataLocateAccessOwnerV1'),(N'AiDataLoadAuthorityV1'),(N'AiDataAuthenticateV1'),(N'AiDataAppendAccessV1'),(N'AiDataAdmitV1'),(N'AiDataSearchCasesV1'),(N'AiDataGetCaseOverviewV1'),(N'AiDataFinishCaseQuotaV1'),(N'AiDataAuthorizeCaseHandoffV1'),(N'AiDataRecordCaseFailureV1'),(N'AiCaseDataInvocation'),(N'AiCaseDataDeployment'),(N'AiDataUnicodeRange'),(N'AiDataUnicodeLower'),(N'AiDataWordTransition'),(N'AiDataNormalizeV1'),(N'AiDataImmutableInvocation'),(N'AiDataImmutableDeployment');
DECLARE @component nvarchar(max);
SET @component=(SELECT CONCAT(o.name,N':',o.type,N':',COALESCE(CONVERT(nvarchar(20),o.principal_id),N''),N':',COALESCE(m.definition,N''),N';') AS [text()] FROM sys.objects o LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.schema_id=SCHEMA_ID(N'dbo') AND o.name IN(SELECT Name FROM @Owned) ORDER BY o.name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 1 AS ComponentOrdinal,N'objects_and_modules' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(OBJECT_NAME(c.object_id),N':',c.name,N':',c.column_id,N':',c.system_type_id,N':',c.max_length,N':',c.precision,N':',c.scale,N':',c.is_nullable,N':',c.is_identity,N':',c.collation_name,N':',cc.definition,N';') AS [text()] FROM sys.columns c LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id WHERE OBJECT_NAME(c.object_id) IN(SELECT Name FROM @Owned) ORDER BY c.object_id,c.column_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 2 AS ComponentOrdinal,N'columns' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(OBJECT_NAME(o.parent_object_id),N':',o.name,N':',o.type,N':',ch.definition,N':',ch.is_disabled,N':',ch.is_not_trusted,N':',dc.definition,N':',fk.referenced_object_id,N':',fk.is_disabled,N':',fk.is_not_trusted,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.check_constraints ch ON ch.object_id=o.object_id LEFT JOIN sys.default_constraints dc ON dc.object_id=o.object_id LEFT JOIN sys.foreign_keys fk ON fk.object_id=o.object_id WHERE OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @Owned) ORDER BY o.object_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 3 AS ComponentOrdinal,N'constraints' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(fkc.constraint_object_id,N':',fkc.parent_column_id,N':',fkc.referenced_column_id,N';') AS [text()] FROM sys.foreign_key_columns fkc WHERE OBJECT_NAME(fkc.parent_object_id) IN(SELECT Name FROM @Owned) ORDER BY fkc.constraint_object_id,fkc.constraint_column_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 4 AS ComponentOrdinal,N'foreign_key_columns' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(OBJECT_NAME(i.object_id),N':',i.name,N':',i.is_unique,N':',i.is_disabled,N':',i.filter_definition,N':',ic.column_id,N':',ic.key_ordinal,N':',ic.is_included_column,N':',ic.is_descending_key,N';') AS [text()] FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id WHERE OBJECT_NAME(i.object_id) IN(SELECT Name FROM @Owned) ORDER BY i.object_id,i.index_id,ic.index_column_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 5 AS ComponentOrdinal,N'indexes' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(p.target_object_id,N':',p.predicate_definition,N':',p.predicate_type,N':',p.operation,N':',sp.is_enabled,N';') AS [text()] FROM sys.security_predicates p JOIN sys.security_policies sp ON sp.object_id=p.object_id WHERE OBJECT_NAME(p.target_object_id) IN(SELECT Name FROM @Owned) ORDER BY p.target_object_id,p.security_predicate_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 6 AS ComponentOrdinal,N'security_predicates' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(p.major_id,N':',p.grantee_principal_id,N':',p.permission_name,N':',p.state,N';') AS [text()] FROM sys.database_permissions p WHERE p.class=1 AND OBJECT_NAME(p.major_id) IN(SELECT Name FROM @Owned) ORDER BY p.major_id,p.grantee_principal_id,p.permission_name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 7 AS ComponentOrdinal,N'object_permissions' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(t.object_id,N':',t.is_disabled,N';') AS [text()] FROM sys.triggers t WHERE t.name IN(SELECT Name FROM @Owned) ORDER BY t.object_id FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 8 AS ComponentOrdinal,N'triggers' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=COALESCE((SELECT CONCAT(name,N':',owning_principal_id,N';') AS [text()] FROM sys.database_principals WHERE name IN(N'AiIntegrationRuntime',N'AiIntegrationBootstrap',N'AiCapabilityOperator') ORDER BY name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)'),N'');
SELECT 9 AS ComponentOrdinal,N'integration_role_owners' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'sec.fn_FilterByTenant')),N'MISSING');
SELECT 10 AS ComponentOrdinal,N'tenant_filter_definition' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(p.class,N':',p.major_id,N':',p.minor_id,N':',p.grantee_principal_id,N':',p.grantor_principal_id,N':',p.permission_name,N':',p.state,N';') AS [text()] FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID(N'AiCaseDataRuntime'),DATABASE_PRINCIPAL_ID(N'AiCaseDataCatalogVerifier')) OR p.class=1 AND OBJECT_NAME(p.major_id) IN(SELECT Name FROM @Owned) ORDER BY p.class,p.major_id,p.minor_id,p.grantee_principal_id,p.permission_name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 11 AS ComponentOrdinal,N'runtime_verifier_permissions' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(o.name,N':',m.execute_as_principal_id,N':',s.principal_id,N';') AS [text()] FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.name IN(SELECT Name FROM @Owned) ORDER BY o.name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 12 AS ComponentOrdinal,N'execution_and_schema_owners' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(OBJECT_NAME(referencing_id),N':',referenced_server_name,N':',referenced_database_name,N':',referenced_schema_name,N':',referenced_entity_name,N';') AS [text()] FROM sys.sql_expression_dependencies WHERE OBJECT_NAME(referencing_id) IN(SELECT Name FROM @Owned) ORDER BY referencing_id,referenced_entity_name FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 13 AS ComponentOrdinal,N'dependencies' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=COALESCE((SELECT CONCAT(name,N':',owning_principal_id) FROM sys.database_principals WHERE name=N'AiCaseDataRuntime'),N'MISSING');
SELECT 14 AS ComponentOrdinal,N'runtime_role_owner' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=COALESCE((SELECT CONCAT(name,N':',owning_principal_id) FROM sys.database_principals WHERE name=N'AiCaseDataCatalogVerifier'),N'MISSING');
SELECT 15 AS ComponentOrdinal,N'verifier_role_owner' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(is_trustworthy_on,N':',is_db_chaining_on) FROM sys.databases WHERE database_id=DB_ID());
SELECT 16 AS ComponentOrdinal,N'database_options' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(StartCodepoint,N':',EndCodepoint,N':',Category,N':',Whitespace,N':',LetterDigit,N':',Cased,N';') AS [text()] FROM dbo.AiDataUnicodeRange ORDER BY StartCodepoint FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 17 AS ComponentOrdinal,N'unicode_ranges' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(Codepoint,N':',CONVERT(varchar(16),CONVERT(varbinary(8),LowerText),2),N';') AS [text()] FROM dbo.AiDataUnicodeLower ORDER BY Codepoint FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 18 AS ComponentOrdinal,N'unicode_lower' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
SET @component=(SELECT CONCAT(StateId,N':',Category,N':',NextState,N':',IsEnd,N':',Lookahead,N';') AS [text()] FROM dbo.AiDataWordTransition ORDER BY StateId,Category FOR XML PATH(''),TYPE).value(N'.',N'nvarchar(max)');
SELECT 19 AS ComponentOrdinal,N'word_transitions' AS ComponentName,DATALENGTH(@component) AS ByteLength,CONVERT(varchar(64),HASHBYTES('SHA2_256',@component),2) AS Sha256;
